        {"항목":"이사야의 신분", "내용":"전승에 따르면 이사야는 왕족 출신으로 궁정에 자유롭게 출입할 수 있었으며, 히브리어 문학 중 가장 세련된 문체를 구사한다", "목회적활용":"하나님은 각 사람의 배경과 재능을 사역에 사용하신다"},
        {"항목":"이사야서의 구조", "내용":"1-39장은 심판 메시지, 40-66장은 위로와 회복 메시지로 구성된다. 1장은 전체 책의 서론이자 요약이다", "목회적활용":"심판의 메시지와 위로의 메시지가 함께 있는 것이 복음의 균형이다"}
