    "표5_매튜헨리": [
        {"영어원문":"The vision of Isaiah — prophets were called seers, because they saw what was to come. Isaiah's name signifies 'the salvation of the Lord,' a very suitable name for this evangelical prophet.", "한국어번역":"이사야의 이상 - 선지자들은 올 일을 보았기에 선견자라 불렸다. 이사야의 이름은 '여호와의 구원'을 의미하니 이 복음적 선지자에게 매우 적합한 이름이다.", "핵심통찰":"이사야의 이름 자체가 복음의 메시지를 담고 있다"},
        {"영어원문":"The prophecy is dated by the reigns of four kings of Judah — this shows that Isaiah had a long and useful ministry, above fifty years.", "한국어번역":"이 예언은 유다 네 왕의 통치로 연대가 표시되니 이사야가 50년 이상 길고 유익한 사역을 했음을 보여준다.", "핵심통찰":"하나님의 종은 오랜 시간 인내하며 충실히 사역해야 한다"},
        {"영어원문":"The vision which he saw concerning Judah and Jerusalem — though he prophesied concerning other nations, his main business was with God's own people.", "한국어번역":"유다와 예루살렘에 관하여 그가 본 이상 - 다른 나라에 대해서도 예언했지만 그의 주된 사역은 하나님의 백성을 향한 것이었다.", "핵심통찰":"하나님의 심판은 세상이 아닌 자기 백성에게서 시작된다"}
    ],
    "표6_설교자료": [
        {"대지":"제목", "내용":"여호와는 구원이시다 - 이사야서의 서막", "예화_적용":"가장 어두운 시대에 가장 밝은 구원의 메시지가 주어졌다"},
        {"대지":"서론", "내용":"이사야서가 시작됩니다. 66장에 걸친 이 위대한 예언서의 첫 절은 선지자의 이름과 시대를 소개합니다. '이사야'는 '여호와는 구원이시다'라는 뜻으로 이 책 전체의 주제를 압축합니다.", "예화_적용":"한 사람의 이름이 평생의 사명이 된 것처럼, 하나님은 우리에게도 고유한 사명을 주셨다"},
        {"대지":"1대지: 이사야의 이름 (구원의 메시지)", "내용":"이사야(예샤야후)는 '여호와는 구원이시다'라는 뜻이다. 이 이름은 예수(예슈아)와 같은 어근을 공유한다. 선지자의 이름 자체가 메시지인 것이다", "예화_적용":"마 1:21 '이름을 예수라 하라 이는 그가 자기 백성을 죄에서 구원할 자이심이라' - 이사야와 예수의 이름이 동일한 구원의 메시지를 담고 있다"},
        {"대지":"2대지: 네 왕의 시대 (역사 속의 하나님)", "내용":"웃시야에서 히스기야까지 약 60년의 격동기. 앗수르의 위협, 북이스라엘의 멸망, 유다의 위기 속에서 하나님은 선지자를 보내셨다", "예화_적용":"세계대전 중에도 본회퍼 같은 선지자적 목소리가 있었듯이, 하나님은 가장 어두운 시대에 빛을 보내신다"},
        {"대지":"3대지: 하나님의 이상 (계시의 방법)", "내용":"이상(하존)은 하나님이 선지자의 영적 눈을 열어 보여주시는 계시이다. 이것은 인간의 생각이 아닌 하나님의 말씀이다", "예화_적용":"암 3:7 '주 여호와께서는 자기의 비밀을 그 종 선지자들에게 보이지 아니하시고는 결코 행하심이 없으시리라'"},
        {"대지":"결론", "내용":"이사야서의 첫 절은 초대장입니다. 하나님의 구원의 이야기 속으로 들어오라는 초대. 이 책을 통해 우리는 심판과 구원, 절망과 소망을 함께 경험하게 될 것입니다.", "예화_적용":"이사야서 66장의 여정이 시작됩니다. 여호와는 구원이시라는 확신을 붙잡고 함께 걸어갑시다"}
    ],
