        {"원어":"פָּשְׁעוּ (파쉐우)", "의미_문법":"거역하다, 반역하다 - 파샤의 완료형, 의도적이고 고의적인 반역", "설교포인트":"죄는 실수가 아니라 하나님에 대한 의도적 반역이다"}
