        {"항목":"고대 의료 행위", "내용":"고대에는 상처를 짜서 고름을 빼고, 붕대로 싸매고, 올리브유를 발라 치료했다. 이 세 단계의 치료가 이루어지지 않았다는 것은 돌보는 이가 없는 상태를 의미한다", "목회적활용":"영적 상처도 적절한 치료가 필요하며, 교회 공동체가 치유의 장소가 되어야 한다"},
        {"항목":"머리에서 발까지", "내용":"5절의 '온 머리'에서 시작하여 6절에서 '발바닥에서 머리까지'로 확대된다. 성한 곳이 없다는 것은 전적 타락의 극적 표현이다", "목회적활용":"부분적 개선이 아닌 전면적 치유가 필요함을 깨닫게 하라"},
        {"항목":"치료받지 못한 상태", "내용":"상처를 짜지도, 싸매지도, 기름을 바르지도 못한 것은 레위기적 정결 규례와 대비된다. 제사장이 해야 할 치유의 역할이 실패했음을 암시한다", "목회적활용":"목회적 돌봄의 부재가 공동체의 영적 건강을 위협한다"}
