        {"상황":"교회의 미래가 불투명하여 불안한 성도", "성경원리":"하나님은 역사 속에서 항상 남은 자를 보존하셨다. 교회의 존재 자체가 은혜의 증거이다", "실제적용":"교회사를 통해 남은 자의 역사를 나누고, 현재 교회가 존재하는 것이 은혜임을 깨닫게 하라"}
