        {"항목":"관원과 백성의 구분", "내용":"관원(지도자)과 백성을 구분하여 부르시는 것은 책임의 차등을 보여준다. 지도자에게 더 큰 책임이 있다", "목회적활용":"영적 지도자에게는 더 큰 책임과 더 엄격한 기준이 적용된다"}
