    "표5_매튜헨리": [
        {"영어원문":"Hear the word of the Lord, ye rulers of Sodom — this was a bold word for Isaiah to say, calling the rulers of God's own people by the name of the most infamous sinners.", "한국어번역":"너희 소돔의 관원들아 여호와의 말씀을 들으라 - 이것은 하나님 자기 백성의 통치자들을 가장 악명 높은 죄인의 이름으로 부르는 대담한 말이었다.", "핵심통찰":"선지자적 설교는 진실을 두려움 없이 선포하는 것이다"},
        {"영어원문":"Give ear unto the law of our God — though he calls them Sodom and Gomorrah, yet he calls God 'our God,' showing that the covenant bond is not broken.", "한국어번역":"우리 하나님의 법에 귀를 기울이라 - 그들을 소돔과 고모라라 부르면서도 하나님을 '우리 하나님'이라 부르니, 언약의 끈이 끊어지지 않았음을 보여준다.", "핵심통찰":"심판 속에서도 하나님의 언약은 지속된다"},
        {"영어원문":"The rulers are addressed first, for they had the greatest influence and should set the example in heeding God's word.", "한국어번역":"통치자들이 먼저 불리는 것은 그들이 가장 큰 영향력을 가지며 하나님의 말씀에 귀 기울이는 본을 보여야 하기 때문이다.", "핵심통찰":"지도자는 하나님의 말씀을 먼저 듣고 순종하는 본을 보여야 한다"}
    ],
    "표6_설교자료": [
        {"대지":"제목", "내용":"소돔의 관원이여 들으라 - 지도자의 책임", "예화_적용":"하나님의 백성의 지도자에게는 더 큰 책임이 있다"},
        {"대지":"서론", "내용":"이사야가 유다의 지도자들을 '소돔의 관원'이라 부릅니다. 이것은 당시 최대의 모욕이었습니다. 하나님의 백성의 지도자가 소돔의 관원과 같다니! 그런데 하나님이 그들에게 원하시는 것은 하나입니다. '들으라.'", "예화_적용":"나단 선지자가 다윗에게 '당신이 그 사람이라' 하듯, 하나님은 지도자를 직접 지목하신다"},
        {"대지":"1대지: 소돔의 관원이라 (지도자의 타락)", "내용":"지도자들이 소돔의 관원이라 불린 것은 그들의 도덕적 타락 때문이다. 23절에서 밝혀지듯 뇌물, 불의, 고아와 과부에 대한 무관심이 그 이유이다", "예화_적용":"교회 지도자의 도덕적 실패가 얼마나 많은 이들에게 상처를 주는지 역사가 증명한다"},
        {"대지":"2대지: 여호와의 말씀을 들으라 (듣는 것의 우선순위)", "내용":"하나님이 요구하시는 첫 번째는 '듣는 것'이다. 행함 이전에 들음이 필요하다. 신 6:4 '이스라엘아 들으라' - 신앙의 시작은 들음이다", "예화_적용":"롬 10:17 '믿음은 들음에서 나며 들음은 그리스도의 말씀으로 말미암느니라'"},
        {"대지":"3대지: 우리 하나님의 법 (언약의 지속)", "내용":"심판 중에도 '우리 하나님'이라 부르신다. 이것은 언약이 끊어지지 않았다는 소망의 메시지이다. 하나님은 심판하시면서도 포기하지 않으신다", "예화_적용":"부모가 자녀를 꾸짖으면서도 '우리 아이'라고 부르듯, 하나님은 심판 중에도 '나의 백성'이라 하신다"},
        {"대지":"결론", "내용":"하나님은 오늘 우리에게도 '들으라'고 말씀하십니다. 소돔의 관원처럼 하나님의 말씀에 무관심하지 않기를 바랍니다. 특히 지도자들은 먼저 듣고 먼저 순종해야 합니다.", "예화_적용":"막 4:9 '들을 귀 있는 자는 들으라' - 듣는 귀를 여시는 것은 성령의 역사이다"}
    ],
