        {"상황":"하나님의 말씀이 잘 안 들린다고 느끼는 성도", "성경원리":"'들으라'는 명령은 의도적 노력을 요구한다. 듣는 것은 자연스러운 것이 아닌 훈련이다", "실제적용":"매일 일정한 시간에 말씀을 읽고 묵상하는 습관을 세우도록 안내하라"},
        {"상황":"교회의 타락에 실망한 성도", "성경원리":"이사야 시대에도 지도자가 타락했지만 하나님의 언약은 지속되었다", "실제적용":"인간 지도자의 실패가 하나님의 신실하심을 부정하지 않음을 알려주고, '우리의 하나님'은 여전하심을 확인시키라"}
