        {"교리":"종교의 역설(Paradox of Religion)", "설명":"하나님이 제정하신 종교 제도가 하나님에게 짐이 되는 역설. 수단이 목적이 되면 하나님을 기쁘시게 하기 위한 것이 하나님을 지치게 한다", "관련구절":"마 23:4, 눅 11:46, 행 15:10"},
        {"교리":"진정성의 요구(Demand for Authenticity)", "설명":"하나님은 진정성을 요구하신다. 형식은 진정성의 표현이어야지 대체물이 되어서는 안 된다", "관련구절":"요 4:23-24, 롬 12:1-2, 시 51:16-17"}
