        {"상황":"과거의 죄로 인한 죄책감에서 자유롭지 못한 성도", "성경원리":"'씻으라'는 하나님의 명령은 깨끗해질 수 있다는 약속을 포함한다", "실제적용":"하나님이 씻으라 명하셨다면 씻어지는 것이 가능하다. 요일 1:9 '우리 죄를 자백하면 우리 죄를 사하시며 모든 불의에서 우리를 깨끗하게 하실 것이요'"}
