    "표8_상담적용": [{"상황":"종합", "성경원리":"이 구절은 교회 공동체에 대한 소속감이 부족한 성도에게 적용된다. '오라 우리가 함께 올라가자'라는 초대는 신앙이 개인주의적이 아닌 공동체적임을 보여준다. 또한 말씀 배움의 즐거움을 잃어버린 성도에게 '그가 그 길로 우리를 가르치실 것이라'는 약속을 통해 말씀 묵상의 기대감을 회복시킬 수 있다.", "실제적용":"본문 내용을 참고하여 적용"}],
