pastorCommentaryData["이사야_2_11"] = {
  "reference": "이사야 2:11",
    "korean_text": "그 날에 사람의 교만한 눈이 낮아지며 사람의 높은 것이 굴복되고 여호와만 홀로 높임을 받으시리라",
    "표1_원어분석": [
        {"원어":"עֵינֵי גַבְהוּת הָאָדָם (에네이 가브후트 하아담)", "의미_문법":"사람의 교만한 눈 - 아인(눈)+가브후트(높음, 교만), 교만은 눈에서 시작됨", "설교포인트":"교만은 높은 곳에서 내려다보는 시선에서 시작된다"},
        {"원어":"שָׁפֵל (샤펠)", "의미_문법":"낮아질 것이다 - 샤팔(낮아지다, 겸손해지다), 강제적 겸손", "설교포인트":"자발적으로 낮아지지 않으면 강제로 낮아지게 된다"},
        {"원어":"וְשַׁח רוּם אֲנָשִׁים (웨샤흐 룸 아나쉼)", "의미_문법":"사람들의 높은 것이 굽혀지고 - 룸(높음)+샤하흐(굽히다), 인간적 위엄의 무력화", "설교포인트":"인간의 모든 자랑이 하나님 앞에서 무너진다"},
        {"원어":"וְנִשְׂגַּב יְהוָה לְבַדּוֹ (웨니스가브 아도나이 레바도)", "의미_문법":"여호와만 홀로 높여지시리라 - 사가브(높아지다)+레바드(홀로, 유일), 하나님의 배타적 높으심", "설교포인트":"종국에는 하나님만이 유일하게 높으신 분으로 드러나신다"}
    ],
    "표2_역사적배경": [{"항목":"종합", "내용":"'그 날'(바욤 하후)은 여호와의 날을 가리키는 예언적 표현으로, 구약 선지서의 핵심 주제이다. 이사야 시대의 교만한 지도자들—부유한 귀족, 군사 지휘관, 제사장—이 여호와의 날에 모두 낮아질 것이라는 선언이다. 이것은 당시 사회의 계급 구조와 권력 남용에 대한 직접적 비판이다.", "목회적활용":"본문 내용을 참고하여 적용"}],
    "표3_신학적의미": [{"교리":"핵심교리", "설명":"이 구절은 이사야 2장의 핵심 주제—인간의 교만과 하나님의 유일한 높으심—을 요약한다. '여호와만 홀로' 높여지신다는 것은 배타적 일신론의 선언이며, 하나님의 절대적 주권을 확인한다. 인간의 교만은 하나님의 자리를 탈취하려는 시도이며, 이는 창세기 3장의 '하나님처럼 되려 한' 원죄의 반복이다.", "관련구절":""}],
    "표4_예표론": [{"구분":"예표", "내용":"사람의 교만이 낮아지고 여호와만 높여지는 것은 빌립보서 2:9-11의 예수 그리스도의 높여지심을 예표한다: '하나님이 그를 지극히 높여 모든 이름 위에 뛰어난 이름을 주사 모든 무릎을 꿇게 하셨다.' 그리스도의 겸손(빌 2:6-8)은 인간의 교만과 정반대이며, 하나님이 높이시는 방법은 먼저 낮아지는 것이다.", "그리스도연결":""}],
    "표5_매튜헨리": [{"영어원문":"", "한국어번역":"매튜 헨리는 이 구절을 이사야 2장의 요약으로 보았다: '전체 장의 메시지가 이 한 절에 담겨 있다—인간은 낮아지고 하나님만 높여지신다. 이것이 역사의 최종 방향이다. 모든 제국, 모든 권력, 모든 인간적 영광은 결국 하나님의 영광 앞에 무릎 꿇게 될 것이다.'", "핵심통찰":""}],
    "표6_설교자료": [{"대지":"설교요약", "내용":"어거스틴은 '하나님의 도성'에서 역사를 하나님의 도성과 인간의 도성의 대결로 해석하며, 최종적으로 하나님의 도성만이 남을 것이라 선언했다. 칼 바르트는 하나님만이 참으로 높으신 분이시므로 인간의 모든 자기 신격화는 우상숭배임을 가르쳤다. 마틴 루터의 십자가 신학도 이 원리에 기초한다.", "예화_적용":""}],
    "표7_찬송가": [
        {"새찬송가":21, "제목":"다 찬양하여라", "선정이유":"하나님만 홀로 높임 받으시기에 합당하심"},
        {"새찬송가":27, "제목":"주 하나님 지으신 모든 세계", "선정이유":"하나님의 위대하심 앞에서 인간의 겸손"}
    ],
    "표8_상담적용": [{"상황":"종합", "성경원리":"이 구절은 교만의 죄와 씨름하는 성도에게 적용된다. 자기 성취, 외모, 지식, 영성 등에서 오는 교만을 점검하게 한다. '여호와만 홀로 높여지신다'는 진리는, 비교와 경쟁에 지친 성도에게 해방감을 줄 수 있다—높아져야 할 의무에서 벗어나, 하나님만 높이는 삶의 자유를 발견하게 한다.", "실제적용":"본문 내용을 참고하여 적용"}],
    "표9_교차참조": [
        {"구절":"빌립보서 2:9-11", "연결점":"하나님이 그를 높이 들어 모든 이름 위에 뛰어난 이름을 주사"},
        {"구절":"잠언 16:18", "연결점":"교만은 패망의 선봉이요 - 교만의 결과"},
        {"구절":"야고보서 4:6", "연결점":"하나님이 교만한 자를 물리치시고 겸손한 자에게 은혜를 주신다"}
    ]
};
