    "표8_상담적용": [{"상황":"종합", "성경원리":"이 구절은 안전에 대한 과도한 집착으로 불안해하는 성도에게 적용된다. 보험, 저축, 건강관리 등 자기 보호 수단 자체는 나쁘지 않지만, 이것들이 하나님보다 더 큰 안전감을 준다면 우상이 될 수 있다. 불안장애를 겪는 성도에게 참된 안전의 근거가 하나님께 있음을 상기시킨다.", "실제적용":"본문 내용을 참고하여 적용"}],
