    "표2_역사적배경": [{"항목":"종합", "내용":"이사야 시대에 웃시야 왕 때 큰 지진이 있었으며(암 1:1, 슥 14:5), 이 경험이 하나님의 심판의 이미지로 사용되었다. 유다 광야에는 사해 주변의 석회암 동굴이 많아 피난처로 사용되었다(삼상 22:1). 이사야는 10절의 이미지를 확장하여 심판의 날의 공포를 더욱 생생하게 묘사한다.", "목회적활용":"본문 내용을 참고하여 적용"}],
    "표3_신학적의미": [{"교리":"핵심교리", "설명":"10절과 19절의 반복은 심판의 불가피성을 강화한다. 인간은 반복적으로 하나님을 피하려 하지만, 편재하시는 하나님을 피할 곳은 없다. '땅을 진동시키려고 일어나심'은 하나님의 우주적 주권을 보여주며, 창조 자체가 하나님의 심판에 반응한다(롬 8:22).", "관련구절":""}],
    "표4_예표론": [{"구분":"예표", "내용":"바위 굴에 숨는 이미지는 요한계시록 6:15-17에서 직접 인용된다. 또한 예수님의 부활 시 '땅이 진동하며 바위가 터지고'(마 27:51)는 사건은 하나님이 일어나시는 것의 신약적 표현이다. 그리스도의 재림 시 온 땅이 진동할 것이며(히 12:26), 이것이 최종 성취이다.", "그리스도연결":""}],
    "표5_매튜헨리": [{"영어원문":"", "한국어번역":"매튜 헨리는 인간의 도피 본능의 헛됨을 묘사했다: '바위 굴과 땅굴에 숨는다고? 바위를 만드시고 땅을 만드신 분이 그 안에 숨은 자를 찾지 못하시겠는가? 요나가 배 밑에 숨어도 하나님은 폭풍으로 찾으셨다. 하나님을 피하는 유일한 길은 하나님께로 돌아가는 것이다.'", "핵심통찰":""}],
    "표6_설교자료": [{"대지":"설교요약", "내용":"루돌프 오토의 '누미노제' 개념은 하나님의 임재 앞에서의 전율을 설명한다. C.S. 루이스는 '고통의 문제'에서 하나님의 심판이 궁극적으로 사랑의 표현임을 논증했다. 조나단 에드워즈의 유명한 설교가 이 구절과 동일한 정서를 전달한다.", "예화_적용":""}],
