    "표8_상담적용": [{"상황":"종합", "성경원리":"이 구절은 자신의 전문성과 능력에 과도하게 의존하는 성도에게 적용된다. 자신이 가진 기술, 지식, 인맥 등이 하나님의 은혜로 주어진 것이며, 언제든 거두어질 수 있음을 인식하게 한다. 은퇴, 해고, 건강 상실 등으로 자신의 역할이 사라진 성도에게 정체성의 근거가 능력이 아닌 하나님과의 관계에 있음을 일깨운다.", "실제적용":"본문 내용을 참고하여 적용"}],
