    "표4_예표론": [{"구분":"예표", "내용":"어린아이의 통치는 이사야 11:6의 '어린아이가 그것들을 이끌며'와 대비된다. 3장에서 어린아이의 통치는 심판이지만, 11장에서 어린아이의 인도는 메시아 시대의 평화를 상징한다. 그리스도의 통치 아래에서 어린아이의 순수함이 회복된다.", "그리스도연결":""}],
