    "표2_역사적배경": [{"항목":"종합", "내용":"고대 이스라엘 사회는 장로 존경, 세대 간 질서, 사회적 위계를 중시했다. 이 구절은 이러한 사회 질서의 완전한 붕괴를 묘사한다. 바벨론 포로기의 혼란, 특히 예레미야 애가에 묘사된 예루살렘의 참상(애 4:16, 5:12)이 이 예언의 역사적 배경이다.", "목회적활용":"본문 내용을 참고하여 적용"}],
    "표3_신학적의미": [{"교리":"핵심교리", "설명":"사회적 질서의 붕괴는 하나님의 질서에 대한 반역의 결과이다. 하나님이 세우신 사회적 구조—가정, 공동체, 국가—가 하나님 없이는 유지될 수 없음을 보여준다. 이것은 로마서 1:28-32에서 바울이 묘사한 '하나님을 인정하기 싫어한' 결과—온갖 악한 행위의 범람—과 동일한 패턴이다.", "관련구절":""}],
    "표4_예표론": [{"구분":"예표", "내용":"사회적 혼란은 마태복음 24:10-12의 종말 징조와 연결된다: '그때에 많은 사람이 실족하고 서로 잡아주고 서로 미워하겠으며...불법이 성하므로 많은 사람의 사랑이 식어지리라.' 그리스도의 재림 전의 사회적 혼란을 예표한다.", "그리스도연결":""}],
    "표5_매튜헨리": [{"영어원문":"", "한국어번역":"매튜 헨리는 사회 해체의 고통을 묘사했다: '어린아이가 노인을 무시하고, 천한 자가 존귀한 자에게 대항하는 사회—이것이 하나님의 심판의 결과이다. 서로 학대하는 사회는 스스로를 파괴하는 사회이다. 이것은 외부의 적보다 더 무서운 내부의 분열이다.'", "핵심통찰":""}],
    "표6_설교자료": [{"대지":"설교요약", "내용":"알렉시스 드 토크빌은 민주주의의 위험 중 하나가 '다수의 횡포'와 전통적 질서의 붕괴라고 경고했다. 이 구절은 사회적 질서의 해체가 가져오는 무법 상태를 보여주며, 교회가 사회의 '소금과 빛'(마 5:13-14)으로서 질서를 유지하는 역할을 해야 함을 상기시킨다.", "예화_적용":""}],
