    "표2_역사적배경": [{"항목":"종합", "내용":"전쟁과 포위로 인해 사회가 완전히 붕괴된 상황을 묘사한다. 옷 한 벌이라도 있는 자가 지도자로 추대되는 것은 극도의 빈곤을 반영한다. 바벨론 포로 후 남은 자들의 상황이나, 앗수르 침공 후 황폐화된 지방 도시들의 모습이 배경이 될 수 있다.", "목회적활용":"본문 내용을 참고하여 적용"}],
    "표3_신학적의미": [{"교리":"핵심교리", "설명":"이 구절은 지도력의 가치가 완전히 전도된 상황을 보여준다. 본래 지도자가 되는 것은 명예였으나, 이제는 아무도 원하지 않는 짐이 되었다. '멸망이 네 수중에 있게 하라'는 것은 성공이 아닌 실패를 관리해야 하는 역할을 의미한다. 이것은 하나님의 심판이 사회 구조를 완전히 전복시킴을 보여준다.", "관련구절":""}],
    "표4_예표론": [{"구분":"예표", "내용":"아무도 원하지 않는 지도자 역할은 그리스도의 겸손한 섬김과 대비된다. 예수님은 아무도 원하지 않는 십자가를 자발적으로 지셨으며(빌 2:8), 멸망을 자기 위에 담당하셨다(사 53:4-5). 세상이 거부한 것을 그리스도가 담당하신 것이 복음의 핵심이다.", "그리스도연결":""}],
    "표5_매튜헨리": [{"영어원문":"", "한국어번역":"매튜 헨리는 이 장면의 비참함을 묘사했다: '겉옷이 있다는 것만으로 지도자가 되어달라고 간청하는 모습을 보라! 이것이 한때 화려했던 예루살렘의 참담한 현실이다. 그리고 그 역할은 영광이 아니라 폐허의 관리이다. 누가 이런 역할을 원하겠는가?'", "핵심통찰":""}],
    "표6_설교자료": [{"대지":"설교요약", "내용":"이 구절은 현대 교회에서 지도자 부재의 위기에 적용할 수 있다. 목회자 수의 감소, 봉사자의 이탈 등의 현실에서, 교회가 지도자 양성과 격려에 힘써야 함을 보여준다.", "예화_적용":""}],
