    "표8_상담적용": [{"상황":"종합", "성경원리":"이 구절은 원하지 않는 책임을 떠맡게 된 성도에게 적용된다. 가장의 역할, 교회 직분, 돌봄의 역할 등을 원하지 않았지만 감당해야 하는 상황에서, 하나님이 함께 하시며 필요한 지혜와 능력을 주실 것이라는 위로를 전한다.", "실제적용":"본문 내용을 참고하여 적용"}],
