    "표2_역사적배경": [{"항목":"종합", "내용":"이 구절은 법정 소송(리브 패턴)의 시작을 알린다. 구약 선지서에서 하나님이 자기 백성을 고소하는 장면은 중요한 문학 형식이다(미 6:1-2, 호 4:1). 하나님이 '일어나시고' '서시는' 것은 재판관이 판결을 내리기 위해 자리에서 일어서는 법정 장면을 연상시킨다.", "목회적활용":"본문 내용을 참고하여 적용"}],
