    "표5_매튜헨리": [{"영어원문":"", "한국어번역":"매튜 헨리는 하나님의 법정 장면의 엄숙함을 묘사했다: '여호와께서 일어나셨다—이것은 더 이상의 인내가 끝났다는 신호이다. 서셨다—재판을 시작하신다는 뜻이다. 이 재판에서 변호사도, 항소도 없다. 하나님이 원고이자 재판관이시기 때문이다.'", "핵심통찰":""}],
