    "표8_상담적용": [{"상황":"종합", "성경원리":"이 구절은 하나님의 심판을 외면하려는 성도에게 적용된다. 하나님이 침묵하시는 것이 동의가 아님을 상기시키며, 지금 회개할 기회가 있을 때 돌아오도록 권면한다. 또한 불의한 상황에서 '하나님은 왜 아무것도 하지 않으시는가' 의문하는 성도에게, 하나님이 심판의 때를 정하시고 반드시 일어나실 것임을 확인시킨다.", "실제적용":"본문 내용을 참고하여 적용"}],
