    "표2_역사적배경": [{"항목":"종합", "내용":"'얼굴에 맷돌질한다'는 표현은 고대 근동에서 가장 강력한 착취의 은유 중 하나이다. 맷돌은 매일의 양식을 준비하는 도구였으나, 여기서는 사람의 얼굴—존엄성과 정체성의 상징—을 가는 잔인한 이미지로 사용된다. 이것은 가난한 자의 인격과 존엄을 완전히 무시하는 착취를 묘사한다.", "목회적활용":"본문 내용을 참고하여 적용"}],
    "표3_신학적의미": [{"교리":"핵심교리", "설명":"'내 백성'이라는 소유격 표현에 주목해야 한다. 하나님이 자기 백성의 고통을 자신의 고통으로 느끼시며, 그 고통의 원인을 제공한 자를 직접 심판하신다. 이것은 마태복음 25:40의 '이 지극히 작은 자 하나에게 한 것이 곧 내게 한 것이니라'의 구약적 표현이다.", "관련구절":""}],
    "표4_예표론": [{"구분":"예표", "내용":"가난한 자의 얼굴이 맷돌질 당하는 것은 이사야 53:5의 고난의 종이 '찔리고 상함을 당하신' 것과 연결된다. 그리스도는 가난한 자의 고통을 자기 몸으로 담당하셨으며, 그들의 얼굴을 회복시키셨다. 부활하신 그리스도의 얼굴의 영광(계 1:16)은 이 수치의 역전이다.", "그리스도연결":""}],
