    "표2_역사적배경": [{"항목":"종합", "내용":"이사야 시대 예루살렘의 귀족 여성들은 이집트, 앗수르, 페니키아에서 수입한 사치품으로 치장했다. 발목에 방울을 달아 짤랑짤랑 소리를 내며 걷는 것은 자신의 존재를 과시하는 행위였다. 이것은 가난한 백성이 굶주리는 상황에서의 극단적 사치로, 사회적 불의의 또 다른 표현이었다.", "목회적활용":"본문 내용을 참고하여 적용"}],
