    "표6_설교자료": [{"대지":"설교요약", "내용":"존 웨슬리는 '돈에 대한 사용'에서 '할 수 있는 만큼 벌고, 할 수 있는 만큼 절약하고, 할 수 있는 만큼 나누라'고 가르쳤다. 이 구절은 과소비와 사치에 대한 성경적 경고로, 소비 문화 속의 그리스도인의 생활 양식을 성찰하게 한다.", "예화_적용":""}],
