    "표5_매튜헨리": [{"영어원문":"", "한국어번역":"매튜 헨리는 심판의 적합성을 지적했다: '교만의 도구가 심판의 도구가 된다. 머리를 높이 든 자의 정수리에 딱지가 생기고, 몸을 과시한 자의 하체가 드러난다. 하나님의 심판은 정확히 죄의 성격에 맞게 적용된다.'", "핵심통찰":""}],
