    "표2_역사적배경": [{"항목":"종합", "내용":"18-23절은 당시 귀족 여성들의 장신구 목록이다. 이 목록은 고고학적으로도 확인되는 고대 근동의 실제 장신구들이다. 초승달 모양 장식은 달의 신 '신(Sin)'과 관련된 이방 종교적 상징이기도 했다. 이러한 장신구의 상당수는 이집트, 페니키아, 메소포타미아에서 수입된 것이었다.", "목회적활용":"본문 내용을 참고하여 적용"}],
    "표3_신학적의미": [{"교리":"핵심교리", "설명":"장신구 목록의 상세한 열거는 물질에 대한 집착의 구체성을 보여준다. 하나님이 이것을 '제거하시겠다'는 것은 인간이 집착하는 모든 것을 하나하나 벗기시는 하나님의 철저한 심판을 의미한다. 이것은 물질적 집착에서의 해방이 자발적으로 이루어지지 않을 때 강제적으로 이루어짐을 보여준다.", "관련구절":""}],
    "표4_예표론": [{"구분":"예표", "내용":"장식의 제거는 그리스도인의 옛 사람을 벗는 것(엡 4:22)을 예표한다. 세상적 치장을 벗어버리고 그리스도를 옷 입는 것(갈 3:27)이 참된 장식이다. 요한계시록 19:8에서 어린 양의 신부는 '빛나고 깨끗한 세마포'를 입으며, 이것은 성도들의 의로운 행실이다.", "그리스도연결":""}],
