        {"원어":"דְּמֵי (데메이)", "의미_문법":"피 - 담(피), 3:15의 억압으로 인한 무고한 피, 또는 제의적 부정", "설교포인트":"무고한 피의 죄는 하나님의 정화로만 씻겨진다"}
