        {"원어":"חֻפָּה (훕파)", "의미_문법":"천막/덮개 - 하파(덮다), 하나님의 보호의 천막, 결혼식의 차양막과 같은 어근", "설교포인트":"하나님의 영광이 보호의 천막이 된다"}
