    "표2_역사적배경": [{"항목":"종합", "내용":"이 구절은 출애굽 시대의 구름기둥과 불기둥(출 13:21-22)의 재현을 약속한다. 또한 시내산에서의 하나님의 현현(출 19:16-18)을 연상시킨다. '훕파'(천막)는 광야의 성막과 연결되며, 하나님이 자기 백성 가운데 거하시는 것을 상징한다. 이것은 새로운 출애굽, 새로운 시내산을 약속하는 것이다.", "목회적활용":"본문 내용을 참고하여 적용"}],
    "표3_신학적의미": [{"교리":"핵심교리", "설명":"이 구절은 하나님의 임재(쉐키나)가 회복된 시온 위에 다시 머무실 것을 약속한다. 구름과 불은 하나님의 영광(카보드)의 가시적 표징이다. '영광 위에 천막'이라는 표현은 하나님의 영광이 보호와 은신처가 됨을 보여주며, 이는 하나님의 임재가 심판이 아닌 보호와 축복으로 경험됨을 의미한다.", "관련구절":""}],
    "표4_예표론": [{"구분":"예표", "내용":"구름과 불의 임재는 성육신하신 그리스도의 예표이다. '말씀이 육신이 되어 우리 가운데 거하시매'(요 1:14)에서 '거하다'는 '장막을 치다'(에스케노센)이며, 이 구절의 '훕파'와 동일한 개념이다. 그리스도 자신이 하나님의 영광의 천막이시다.", "그리스도연결":""}],
    "표5_매튜헨리": [{"영어원문":"", "한국어번역":"매튜 헨리는 출애굽과의 연결을 강조했다: '구름기둥과 불기둥이 다시 나타난다! 이것은 새로운 출애굽이다. 하나님이 옛날 광야에서 하셨던 것처럼 다시 하실 것이다. 낮에는 구름으로 덥지 않게, 밤에는 불로 어둡지 않게 하시며, 영광의 천막으로 모든 것을 덮으신다.'", "핵심통찰":""}],
    "표6_설교자료": [{"대지":"설교요약", "내용":"위르겐 몰트만은 '성령의 능력 안에 있는 교회'에서 하나님의 임재가 교회의 본질이라고 강조했다. 교회가 교회인 이유는 건물이나 조직이 아니라 하나님의 임재 때문이다. 이 구절은 참된 교회의 표지가 하나님의 영광의 임재임을 보여준다.", "예화_적용":""}],
