    "표6_설교자료": [{"대지":"설교요약", "내용":"이 포도원의 노래는 구약에서 가장 뛰어난 예언적 시문학 중 하나이다. 존 오스왈트는 이 노래가 나단의 비유(삼하 12:1-7)와 유사한 수사적 전략—청중을 끌어들인 후 그들 자신을 향해 돌리는—을 사용한다고 분석했다.", "예화_적용":""}],
