    "표8_상담적용": [{"상황":"종합", "성경원리":"이 구절은 하나님의 사랑을 의심하는 성도에게 적용된다. 하나님이 자기 백성을 '사랑하는 자'의 포도원으로 부르시며, 기름진 산에 심으셨다는 것은 우리를 향한 하나님의 세심한 관심과 사랑을 보여준다. 자기가 사랑받을 가치가 없다고 느끼는 성도에게 하나님의 선제적 사랑을 확인시킨다.", "실제적용":"본문 내용을 참고하여 적용"}],
