    "표2_역사적배경": [{"항목":"종합", "내용":"포도 재배 과정이 상세히 묘사되어 있다: 땅 파기, 돌 제거, 최고급 품종 심기, 망대 건설, 술틀 설치. 이 모든 과정은 수년의 노동을 필요로 했다. '소레크' 포도는 소렉 골짜기(삼손의 들릴라 이야기, 삿 16:4)에서 유래한 최고급 품종이었다. 그러나 결과는 '들포도'(베우쉼)—쓰고 먹을 수 없는 열매였다.", "목회적활용":"본문 내용을 참고하여 적용"}],
    "표3_신학적의미": [{"교리":"핵심교리", "설명":"이 구절은 하나님의 투자와 이스라엘의 배반 사이의 극적 대비를 보여준다. 하나님이 할 수 있는 모든 것을 다 하셨음에도 결과는 실패였다. 이것은 인간의 자유의지와 책임을 강조한다—하나님의 은혜만으로는 충분하지 않으며, 인간의 응답이 필요하다. 동시에 죄의 불합리성을 보여준다—최상의 조건에서도 인간은 죄를 선택한다.", "관련구절":""}],
    "표4_예표론": [{"구분":"예표", "내용":"포도원의 비유는 요한복음 15:1-8의 포도나무와 가지 비유와 연결된다. 예수님은 '나는 참 포도나무요 아버지는 농부'라 하시며, 열매 맺지 못하는 가지는 잘려나갈 것을 경고하셨다. 하나님의 기대는 좋은 열매이며, 열매 없는 신앙은 진짜가 아니다.", "그리스도연결":""}],
    "표5_매튜헨리": [{"영어원문":"", "한국어번역":"매튜 헨리는 하나님의 실망을 전했다: '파고, 돌을 치우고, 최고급 포도를 심고, 망대를 세우고, 술틀까지 팠다. 이보다 더 무엇을 할 수 있었겠는가? 그런데 결과는 들포도! 하나님의 마음이 얼마나 아프셨겠는가? 이것이 죄의 비합리성이다—모든 것을 받고도 뒤돌아서는 것.'", "핵심통찰":""}],
    "표6_설교자료": [{"대지":"설교요약", "내용":"이 구절은 '성과 없는 투자'의 비유로 현대에 적용할 수 있다. 부모의 헌신에도 불구하고 방황하는 자녀, 교회의 양육에도 불구하고 세속화되는 성도 등에 적용하면서, 궁극적으로 이것이 하나님의 마음을 아프게 하는 것임을 전할 수 있다.", "예화_적용":""}],
