    "표8_상담적용": [{"상황":"종합", "성경원리":"이 구절은 하나님의 기대에 부응하지 못한 죄책감을 가진 성도에게 적용된다. 하나님이 모든 것을 투자하셨음을 인정하면서도, '들포도'의 현실에서 돌아와 '좋은 포도'를 맺을 수 있는 가능성은 여전히 열려 있음을 전한다. 회개와 새 출발을 격려한다.", "실제적용":"본문 내용을 참고하여 적용"}],
