    "표3_신학적의미": [{"교리":"핵심교리", "설명":"하나님이 청중에게 판단을 맡기시는 것은 하나님의 심판이 임의적이 아니라 공정함을 보여주기 위함이다. 객관적으로 보면 포도원 주인(하나님)에게 잘못이 없음이 자명하다. 이것은 로마서 3:4의 '하나님은 참되시되 모든 사람은 거짓되다'는 원리의 구약적 표현이다.", "관련구절":""}],
    "표4_예표론": [{"구분":"예표", "내용":"하나님이 백성에게 판단을 요청하시는 것은 예수님의 비유적 질문과 동일하다. 마태복음 21:40에서 예수님은 '포도원 주인이 올 때 그 농부들을 어떻게 하겠느냐?'고 물으셨다. 그들은 스스로 '그 악한 자들을 멸하리이다'라고 답하며 자기 심판을 선언했다.", "그리스도연결":""}],
