    "표3_신학적의미": [{"교리":"핵심교리", "설명":"이 구절은 하나님의 보호가 은혜이며, 그것이 거두어질 수 있음을 보여준다. 하나님의 보호를 당연시하는 교만이 보호의 제거를 초래한다. 이것은 '일반 은총'의 신학과 연결된다—비가 오고 해가 뜨는 것도 하나님의 은혜이며, 이것이 없어지면 모든 것이 무너진다.", "관련구절":""}],
    "표4_예표론": [{"구분":"예표", "내용":"울타리가 제거된 포도원은 이방에 넘겨진 이스라엘을 예표하며, 궁극적으로 그리스도를 거부한 이스라엘에서 교회로 포도원이 넘겨지는 것(마 21:43)을 예표한다. 에베소서 2:14에서 그리스도는 유대인과 이방인 사이의 '담'을 허셨으나, 이것은 심판이 아닌 은혜의 행위이다.", "그리스도연결":""}],
