    "표6_설교자료": [{"대지":"설교요약", "내용":"이 구절은 교회의 영적 보호에 대한 교훈을 준다. 하나님의 보호 아래 있는 것을 당연시할 때, 그 보호가 거두어질 수 있다. 조나단 에드워즈의 '진노하신 하나님의 손에 있는 죄인들'은 이 원리를 극적으로 전달한다.", "예화_적용":""}],
