    "표2_역사적배경": [{"항목":"종합", "내용":"이 구절은 포도원 비유의 해석이자 결론이다. 히브리어 원문의 언어유희(미쉬파트-미스파흐, 체다카-체아카)는 번역으로 전달하기 어려운 탁월한 수사적 효과를 가진다. 발음이 비슷한 두 단어가 정반대의 의미를 가지는 것은, 이스라엘이 하나님의 기대에서 얼마나 크게 벗어났는지를 극적으로 보여준다.", "목회적활용":"본문 내용을 참고하여 적용"}],
    "표3_신학적의미": [{"교리":"핵심교리", "설명":"하나님이 바라시는 것은 명확하다—정의(미쉬파트)와 공의(체다카). 그러나 실제로는 포학(미스파흐)과 부르짖음(체아카)이 있었다. 이것은 사회 정의가 하나님 나라의 핵심 가치임을 보여준다. 종교적 제의(1:11-15)가 사회 정의 없이는 무의미함을 재확인한다.", "관련구절":""}],
    "표4_예표론": [{"구분":"예표", "내용":"정의 대신 포학, 공의 대신 부르짖음이 있는 이스라엘은 그리스도의 십자가 사건에서 극대화된다. 무죄한 자가 유죄 판결을 받고(정의→포학), 의로우신 분이 십자가에서 부르짖으신다(공의→부르짖음, 마 27:46). 그러나 그 부르짖음을 통해 참된 정의와 공의가 회복된다.", "그리스도연결":""}],
    "표5_매튜헨리": [{"영어원문":"", "한국어번역":"매튜 헨리는 언어유희의 효과를 설명했다: '이사야의 천재적 언어유희! 정의(미쉬파트)가 포학(미스파흐)으로, 공의(체다카)가 부르짖음(체아카)으로. 한 글자의 차이가 천지 차이를 만든다. 이것이 이스라엘의 비극이다—가까이에 있으면서도 완전히 벗어난 것.'", "핵심통찰":""}],
    "표6_설교자료": [{"대지":"설교요약", "내용":"발터 브루게만은 이 언어유희를 '예언적 상상력'의 대표적 사례로 분석했다. 코넬리우스 플란팅가는 '세상이 마땅히 되어야 하는 것'에서 하나님의 샬롬이 정의와 공의를 포함함을 강조하며, 이 구절을 인용했다.", "예화_적용":""}],
