    "표2_역사적배경": [{"항목":"종합", "내용":"이 구절은 이사야의 6가지 화 선언(5:8-23) 중 첫 번째이다. 이사야 시대에 부유한 지주들이 가난한 소농의 토지를 빼앗아 대토지를 형성하는 것이 심각한 사회 문제였다. 율법은 토지가 영구히 팔리지 못하도록 했으나(레 25:23), 이 규정이 무시되었다. 미가 2:2도 동일한 문제를 비판한다.", "목회적활용":"본문 내용을 참고하여 적용"}],
    "표3_신학적의미": [{"교리":"핵심교리", "설명":"토지 독점에 대한 첫 번째 화 선언은 탐욕의 죄를 다룬다. 율법에 따르면 땅은 하나님의 것이며(레 25:23), 인간은 관리자에 불과하다. 토지를 독점하는 것은 하나님의 소유권을 부정하고 이웃의 생존권을 빼앗는 이중의 죄이다.", "관련구절":""}],
    "표4_예표론": [{"구분":"예표", "내용":"토지 독점에 대한 심판은 예수님의 '부자와 나사로' 비유(눅 16:19-31)와 '바보 부자' 비유(눅 12:16-21)와 연결된다. 탐욕은 신약에서도 '우상숭배'(골 3:5)로 정의되며, 하나님 나라에 들어가는 데 가장 큰 장애물 중 하나이다.", "그리스도연결":""}],
    "표5_매튜헨리": [{"영어원문":"", "한국어번역":"매튜 헨리는 탐욕의 끝없음을 비판했다: '집에 집을, 밭에 밭을—끝이 없다! 탐욕은 채워지지 않는 구덩이와 같다. 모든 것을 독점하고도 만족하지 못한다. 그리고 이 과정에서 가난한 자의 터전이 사라진다. 이것이 하나님의 첫 번째 화를 부르는 죄이다.'", "핵심통찰":""}],
