    "표2_역사적배경": [{"항목":"종합", "내용":"이 구절은 8절의 토지 독점에 대한 심판이다. 독점한 집과 땅이 황폐해지는 것은 바벨론 포로로 인한 인구 이동의 결과이다. BC 586년 예루살렘 멸망 후 귀족들의 화려한 저택은 텅 빈 폐허가 되었다.", "목회적활용":"본문 내용을 참고하여 적용"}],
    "표3_신학적의미": [{"교리":"핵심교리", "설명":"탐욕의 심판은 탐욕의 대상 자체의 파괴로 나타난다. 많은 집을 소유하려 했으나 모든 집이 비게 되고, 넓은 토지를 확보했으나 경작할 사람이 없게 된다. 이것은 전도서의 '허무'(헤벨) 주제와 연결된다—세상의 것을 아무리 많이 모아도 결국 공허하다.", "관련구절":""}],
