    "표6_설교자료": [{"대지":"설교요약", "내용":"이 구절은 부동산 투기와 과도한 재산 축적에 대한 경고로 적용할 수 있다. 빈 아파트, 공실 상가 등 현대의 부동산 과잉 현상이 이 구절의 현대적 반영이다.", "예화_적용":""}],
