    "표2_역사적배경": [{"항목":"종합", "내용":"이 구절은 농업적 재앙을 묘사한다. 10에이커의 포도원에서 겨우 한 바트(22리터)의 포도주만 나온다는 것은 정상 수확의 극히 일부에 불과하다. 한 호멜(220리터)의 씨를 뿌리고 한 에바(22리터)만 수확한다는 것은 10분의 1의 수확률로, 사실상 기근이다.", "목회적활용":"본문 내용을 참고하여 적용"}],
    "표3_신학적의미": [{"교리":"핵심교리", "설명":"이 구절은 신명기 28:38-42의 불순종에 대한 저주의 실현이다. '많이 뿌리나 적게 거둔다'는 것은 노동의 허무함을 의미하며, 이것은 하나님의 축복이 없는 노동의 결과이다. 학개 1:6의 '많이 뿌려도 수확이 적고'와 동일한 원리이다.", "관련구절":""}],
    "표4_예표론": [{"구분":"예표", "내용":"적은 수확의 저주는 그리스도 안에서의 풍성한 열매(요 15:5)와 대비된다. 그리스도 안에 거하면 많은 열매를 맺지만, 그리스도 밖에서는 아무것도 할 수 없다. 오병이어의 기적(요 6:1-14)은 하나님의 축복이 있으면 적은 것이 풍성해짐을 보여준다.", "그리스도연결":""}],
    "표5_매튜헨리": [{"영어원문":"", "한국어번역":"매튜 헨리는 수치를 강조했다: '10에이커에서 22리터! 씨의 1/10만 수확! 이것은 거의 완전한 실패이다. 아무리 열심히 일해도 하나님의 축복이 없으면 이것이 결과이다. 탐욕으로 넓힌 땅이 오히려 수치가 된다.'", "핵심통찰":""}],
    "표6_설교자료": [{"대지":"설교요약", "내용":"이 구절은 하나님의 축복 없는 노동의 허무함을 가르치는 데 효과적이다. 시편 127:1-2의 '여호와께서 세우지 아니하시면 세우는 자의 수고가 헛되다'와 함께 읽을 수 있다.", "예화_적용":""}],
    "표7_찬송가": [
        {"새찬송가":"430", "제목":"순종하면 축복이오", "선정이유":"순종의 축복과 불순종의 저주의 대비"},
        {"새찬송가":"460", "제목":"지금까지 지내온 것", "선정이유":"모든 수확이 하나님의 은혜였음을 감사"}
    ],
    "표8_상담적용": [{"상황":"종합", "성경원리":"이 구절은 열심히 일하지만 성과가 없어 좌절하는 성도에게 적용된다. 노력의 결과가 하나님의 축복에 달려 있음을 인정하고, 먼저 하나님과의 관계를 점검하도록 안내한다. 동시에 모든 성과 부진이 심판은 아니므로 균형 잡힌 해석이 필요하다.", "실제적용":"본문 내용을 참고하여 적용"}],
