    "표2_역사적배경": [{"항목":"종합", "내용":"이사야의 세 번째 화(禍) 선언이다. 당시 유다 사회에서 사람들이 죄를 단순히 '빠지는' 것이 아니라 의도적으로 '끌어당기고' 있었다. 거짓 논리와 자기 합리화로 죄를 정당화하며 적극적으로 악을 추구하는 풍조가 만연했다. 이것은 단순한 연약함이 아니라 의도적 반역이었다.", "목회적활용":"본문 내용을 참고하여 적용"}],
    "표3_신학적의미": [{"교리":"핵심교리", "설명":"죄의 진행적 본질을 보여주는 강력한 이미지이다. 처음에는 '거짓의 가는 끈'으로 시작하지만 점차 '수레줄'처럼 굵어진다. 이것은 죄의 점진적 강화를 나타낸다. 또한 죄를 '끄는' 행위는 능동적이고 의도적인 것으로, 단순한 유혹에 넘어감과 구별된다. 인간은 죄의 피해자가 아니라 공모자가 될 수 있다.", "관련구절":""}],
