    "표5_매튜헨리": [{"영어원문":"", "한국어번역":"매튜 헨리는 이 구절에서 죄의 교활한 진행과정을 설명한다. 처음에는 가느다란 거짓의 끈으로 시작하여, 습관이 되면 굵은 수레줄이 된다. 죄인들은 마치 짐승이 수레를 끄는 것처럼 자발적으로 죄악을 끌고 다닌다. 더 심각한 것은 그들이 이것을 부끄러워하지 않고 오히려 당당하게 행한다는 점이다.", "핵심통찰":""}],
    "표6_설교자료": [{"대지":"설교요약", "내용":"설교 제목: '끈에서 밧줄로 - 죄의 진행'\n\n본론:\n1. 거짓의 가느다란 끈 - 죄는 작은 자기합리화에서 시작된다\n2. 수레의 굵은 밧줄 - 반복된 타협은 강력한 속박이 된다\n3. 자발적으로 끄는 자 - 죄의 가장 위험한 단계는 의도적 추구이다\n\n적용: 내 안의 작은 자기합리화가 무엇인지 점검하라. 가느다란 끈일 때 끊어야 한다.", "예화_적용":""}],
