    "표3_신학적의미": [{"교리":"핵심교리", "설명":"하나님의 인내(롱서퍼링)를 오해하는 인간의 교만을 폭로한다. 심판이 즉시 오지 않는 것은 하나님의 무능이 아니라 은혜의 시간이다(베드로후서 3:9). 그러나 은혜의 시간을 조롱의 기회로 삼는 것은 은혜를 방자한 것으로 바꾸는 행위이다(유다서 1:4). 하나님의 뜻(עֲצָה)은 인간의 조롱에도 불구하고 반드시 성취된다.", "관련구절":""}],
