    "표5_매튜헨리": [{"영어원문":"", "한국어번역":"매튜 헨리는 이들의 조롱이 '이중의 죄'라고 지적한다. 첫째, 하나님의 심판을 믿지 않는 불신이요, 둘째, 하나님의 인내를 악용하는 교만이다. 하나님이 심판을 지체하시는 것은 회개의 기회를 주시기 위함인데, 이들은 이 기회를 더 큰 죄를 짓는 데 사용했다. 하나님의 인내를 시험하는 것은 가장 어리석은 행위이다.", "핵심통찰":""}],
    "표6_설교자료": [{"대지":"설교요약", "내용":"설교 제목: '하나님의 인내를 시험하는 자들'\n\n본론:\n1. 조롱의 뿌리 - 하나님의 인내를 무능으로 오해함\n2. 은혜의 시간 - 심판의 지체는 회개의 기회이다\n3. 반드시 이루어지는 뜻 - 하나님의 계획은 인간의 시간표를 따르지 않는다\n\n적용: 하나님이 즉시 응답하지 않으신다고 그분의 말씀을 의심하고 있지는 않은가?", "예화_적용":""}],
