    "표2_역사적배경": [{"항목":"종합", "내용":"당시 유다의 군사 지도자들과 귀족들이 연회에서 음주를 자랑하는 풍조가 있었다. 고대 근동에서 포도주에 향료나 약초를 섞어 더 강한 술을 만드는 것이 일반적이었다. '용사(גִּבּוֹר)'라는 단어는 본래 전쟁 영웅을 지칭하는데, 이들이 전장이 아닌 연회장에서 '용맹'을 발휘한다는 아이러니를 담고 있다.", "목회적활용":"본문 내용을 참고하여 적용"}],
    "표3_신학적의미": [{"교리":"핵심교리", "설명":"하나님이 주신 능력과 지위를 잘못 사용하는 죄를 지적한다. 나라를 지켜야 할 '용사'들이 음주로 능력을 낭비하고 있다. 이것은 청지기직의 왜곡이며, 탈란트 비유(마태복음 25장)의 한 달란트를 땅에 묻은 종보다 더 심각하다. 받은 은사를 자기 쾌락에 탕진하는 것이기 때문이다.", "관련구절":""}],
    "표4_예표론": [{"구분":"예표", "내용":"술에 취한 용사들의 이미지는 그리스도의 잔과 대비된다. 예수님은 겟세마네에서 고난의 잔을 마시셨고(마태복음 26:39), 이것이 참된 용기이다. 세상의 용사는 쾌락의 잔에서 용기를 얻지만, 그리스도의 제자는 고난의 잔에서 참된 능력을 얻는다.", "그리스도연결":""}],
    "표5_매튜헨리": [{"영어원문":"", "한국어번역":"매튜 헨리는 이 구절에서 '잘못된 용기'의 위험을 경고한다. 술로 얻는 용기는 거짓 용기이며, 진정한 용기는 하나님을 경외하는 데서 나온다. 지도자들이 공의를 행하는 데는 겁쟁이이면서 음주에만 용감한 것은 가장 비극적인 도덕적 전도이다. 이런 지도자 아래서 백성은 고통받을 수밖에 없다.", "핵심통찰":""}],
    "표6_설교자료": [{"대지":"설교요약", "내용":"설교 제목: '잘못된 곳에서의 용맹'\n\n본론:\n1. 술의 용사 - 잘못된 곳에서 능력을 발휘하는 비극\n2. 거짓 용기 - 술이 주는 담대함은 진정한 용기가 아니다\n3. 참된 용사 - 하나님 앞에서 정의를 행하는 것이 진정한 용맹이다\n\n적용: 나의 시간과 에너지와 능력이 잘못된 곳에 쏟아지고 있지 않은가?", "예화_적용":""}],
