    "표2_역사적배경": [{"항목":"종합", "내용":"고대 전쟁에서 장거리 행군의 가장 큰 적은 피로와 장비 고장이었다. 이사야는 하나님이 부르신 군대가 이 모든 문제에서 자유롭다고 묘사한다. 이것은 앗수르 군대의 유명한 효율성과 기동력을 반영하면서도, 그 능력의 궁극적 원천이 하나님임을 강조한다.", "목회적활용":"본문 내용을 참고하여 적용"}],
