    "표5_매튜헨리": [{"영어원문":"", "한국어번역":"매튜 헨리는 이 군대의 완벽한 상태에서 하나님의 심판의 확실성을 읽는다. 인간의 군대는 피로, 질병, 탈영 등으로 약해지지만, 하나님이 보내신 군대는 아무것도 그들을 막지 못한다. 허리띠 하나, 신들메 하나까지 완벽한 것은 하나님의 세밀한 섭리를 보여준다.", "핵심통찰":""}],
    "표6_설교자료": [{"대지":"설교요약", "내용":"설교 제목: '완벽하게 준비된 하나님의 계획'\n\n본론:\n1. 지치지 않는 군대 - 하나님의 심판은 방해받지 않는다\n2. 잠들지 않는 파수꾼 - 하나님의 계획은 쉼 없이 진행된다\n3. 끊어지지 않는 신들메 - 세부 사항까지 완벽한 섭리\n\n적용: 하나님의 계획은 완벽하게 이루어진다. 나는 그 계획에 순종하고 있는가?", "예화_적용":""}],
