    "표2_역사적배경": [{"항목":"종합", "내용":"문지방이 흔들리고 연기가 가득한 장면은 출애굽기 19장의 시내산 현현을 연상시킨다. 시내산에서도 산이 떨고 연기가 올랐다. 이것은 하나님의 임재가 시내산에서 성전으로, 그리고 선지자의 소명으로 이어지는 연속성을 보여준다. 솔로몬 성전 봉헌 때도 영광의 구름이 성전에 가득했다(열왕기상 8:10-11).", "목회적활용":"본문 내용을 참고하여 적용"}],
    "표3_신학적의미": [{"교리":"핵심교리", "설명":"하나님의 임재가 물리적 세계에 실재적 영향을 미침을 보여준다. 문지방의 기초가 흔들리는 것은 인간이 만든 가장 견고한 구조물도 하나님의 임재 앞에서는 불안정함을 나타낸다. 연기는 하나님의 영광의 구름(쉐키나)과 관련되며, 동시에 인간이 하나님을 직접 볼 수 없음을 상징한다.", "관련구절":""}],
    "표4_예표론": [{"구분":"예표", "내용":"성전에 충만한 연기는 요한계시록 15:8에서 '하나님의 영광과 능력으로 말미암아 성전에 연기가 가득 찬' 장면과 연결된다. 또한 오순절에 성령이 '불의 혀 같이 갈라지는 것'으로 임하신 것(사도행전 2:3)은 하나님의 임재의 불과 연기 모티프의 신약적 성취이다.", "그리스도연결":""}],
    "표5_매튜헨리": [{"영어원문":"", "한국어번역":"매튜 헨리는 이 장면에서 하나님의 임재의 실재성을 강조한다. 삼성송의 소리에 성전의 기초가 흔들린 것은 하나님의 말씀이 얼마나 강력한지를 보여준다. 연기는 하나님의 거룩한 임재를 가리면서 동시에 드러내는 이중적 역할을 한다. 인간은 하나님을 완전히 알 수 없지만, 그분의 임재를 경험할 수 있다.", "핵심통찰":""}],
    "표6_설교자료": [{"대지":"설교요약", "내용":"설교 제목: '흔들리는 문지방, 충만한 연기'\n\n본론:\n1. 흔들리는 기초 - 하나님의 임재는 모든 것을 흔든다\n2. 충만한 연기 - 하나님의 영광은 가려지면서 드러난다\n3. 실재적 경험 - 하나님의 임재는 추상이 아닌 실재이다\n\n적용: 우리의 예배가 문지방을 흔드는 하나님의 임재를 경험하고 있는가?", "예화_적용":""}],
