    "표2_역사적배경": [{"항목":"종합", "내용":"성전의 제단에서 불을 가져오는 것은 그 불이 일반적인 불이 아니라 하나님께 바쳐진 거룩한 불임을 의미한다. 레위기 10:1-2에서 나답과 아비후가 '다른 불'을 드려 죽임당한 사건을 상기시킨다. 하나님의 불만이 정결케 할 수 있다. 부젓가락을 사용한 것은 그 불의 강렬한 거룩함을 나타낸다.", "목회적활용":"본문 내용을 참고하여 적용"}],
    "표3_신학적의미": [{"교리":"핵심교리", "설명":"하나님의 주도적 은혜를 극적으로 보여준다. 이사야가 자신을 정결케 한 것이 아니라, 스랍이 하나님의 명에 따라 제단의 불을 가져와 정결케 했다. 인간은 자신의 죄를 스스로 해결할 수 없으며, 하나님의 은혜만이 죄를 태워 없앨 수 있다. 제단의 불은 속죄의 희생과 연결되며, 이것이 정결의 근거이다.", "관련구절":""}],
