    "표5_매튜헨리": [{"영어원문":"", "한국어번역":"매튜 헨리는 이 장면에서 '은혜의 주도성'을 강조한다. 이사야가 자기 죄를 고백했을 때, 하나님은 즉시 은혜를 베푸셨다. 스랍이 '날아왔다'는 표현은 은혜의 신속함을 보여준다. 하나님은 회개하는 자에게 즉시 달려오시는 분이다. 탕자의 아버지가 달려간 것과 같다(누가복음 15:20).", "핵심통찰":""}],
    "표6_설교자료": [{"대지":"설교요약", "내용":"설교 제목: '제단에서 온 숯불'\n\n본론:\n1. 날아오는 은혜 - 하나님의 은혜는 주도적이고 신속하다\n2. 제단의 불 - 정결의 근거는 속죄의 희생이다\n3. 숯불의 아픔 - 정결케 하심에는 고통이 수반되지만 치유가 따른다\n\n적용: 하나님의 정결케 하시는 은혜를 구하고 있는가? 그 과정의 아픔을 두려워하고 있지는 않은가?", "예화_적용":""}],
