    "표2_역사적배경": [{"항목":"종합", "내용":"이 구절은 이사야의 사명이 '성공'이 아닌 '선포' 자체에 있음을 보여준다. 백성이 듣지 않을 것을 알면서도 전하라는 명령이다. 이 말씀은 신약에서 가장 많이 인용되는 구약 구절 중 하나이다. 예수님이 비유를 사용하시는 이유를 설명할 때(마태복음 13:14-15), 바울이 유대인의 불신을 설명할 때(사도행전 28:26-27) 이 구절을 인용한다.", "목회적활용":"본문 내용을 참고하여 적용"}],
    "표3_신학적의미": [{"교리":"핵심교리", "설명":"이것은 성경에서 가장 어려운 신학적 문제 중 하나인 '사법적 경화(judicial hardening)'를 다룬다. 하나님이 백성의 마음을 굳게 하신다는 것인가, 아니면 그들의 이미 굳어진 마음을 확인하시는 것인가? 대부분의 해석자들은 후자를 지지한다: 백성이 스스로 마음을 닫았기에 하나님이 그 상태를 확정하신 것이다.", "관련구절":""}],
    "표4_예표론": [{"구분":"예표", "내용":"예수님은 마태복음 13:14-15에서 이 구절을 직접 인용하며 비유 교훈의 이유를 설명하셨다. 비유는 열린 마음에게는 진리를 열어주지만, 닫힌 마음에게는 더 닫히게 한다. 바울도 사도행전 28:26-27에서 유대인의 복음 거부를 이 예언의 성취로 해석했다.", "그리스도연결":""}],
    "표5_매튜헨리": [{"영어원문":"", "한국어번역":"매튜 헨리는 이 구절에서 '하나님의 가장 무서운 심판'을 발견한다. 가장 무서운 심판은 외적 재난이 아니라 영적 무감각이다. 듣되 깨닫지 못하고, 보되 알지 못하는 것은 영적 죽음의 상태이다. 이것은 은혜를 반복적으로 거부한 결과이며, 하나님이 그 거부를 확정하시는 것이다.", "핵심통찰":""}],
    "표6_설교자료": [{"대지":"설교요약", "내용":"설교 제목: '들어도 깨닫지 못하는 비극'\n\n본론:\n1. 들으면서 듣지 못함 - 영적 청각 장애의 실체\n2. 보면서 보지 못함 - 영적 시각 장애의 원인\n3. 은혜 거부의 결과 - 반복된 거부가 영적 무감각을 만든다\n\n적용: 하나님의 말씀이 내 마음에 닿고 있는가? 습관적 경청이 참된 순종으로 이어지고 있는가?", "예화_적용":""}],
