    "표2_역사적배경": [{"항목":"종합", "내용":"이 구절은 이사야의 사명의 역설적 측면을 가장 극적으로 보여준다. 선지자의 메시지가 백성을 구원하는 것이 아니라 오히려 마음을 더 굳게 한다. 이것은 백성이 이미 오랜 기간 하나님의 말씀을 거부해온 결과이다. 바로의 마음이 굳어진 것(출애굽기 7-14장)과 유사한 패턴이다.", "목회적활용":"본문 내용을 참고하여 적용"}],
    "표3_신학적의미": [{"교리":"핵심교리", "설명":"가장 깊은 수준의 신학적 긴장이 드러나는 구절이다. 하나님이 마음을 굳게 하시면서도 '치유받을까 하노라'고 말씀하시는 것은, 하나님의 주권과 인간의 책임, 심판과 은혜의 긴장을 동시에 보여준다. 칼빈은 이를 하나님의 주권적 예정으로, 아르미니우스는 인간의 자유의지에 대한 하나님의 응답으로 해석했다.", "관련구절":""}],
