    "표5_매튜헨리": [{"영어원문":"", "한국어번역":"매튜 헨리는 이 구절에서 하나님의 심판의 가장 깊은 형태를 설명한다. 외적 재난보다 더 무서운 것은 내적 경화이다. 마음이 둔해지고, 귀가 막히고, 눈이 감기면 구원의 메시지 자체가 도달할 수 없다. 그러나 '고침을 받을까'라는 표현에서 하나님이 여전히 치유를 원하시는 마음을 읽을 수 있다.", "핵심통찰":""}],
    "표6_설교자료": [{"대지":"설교요약", "내용":"설교 제목: '닫힌 마음의 비극'\n\n본론:\n1. 둔해진 마음 - 반복된 불순종이 영적 감각을 마비시킨다\n2. 막힌 귀, 감긴 눈 - 진리를 인지할 능력조차 상실하는 비극\n3. '고침받을까' - 심판 속에 숨겨진 하나님의 치유 의지\n\n적용: 하나님의 말씀에 대한 나의 감수성은 어떠한가? 점점 무뎌지고 있지는 않은가?", "예화_적용":""}],
